using namespace std;

class Fenwick {
    vector<long long> tree;
public:
    Fenwick(int sz) : tree(sz + 2, 0) {}
    void add(int i, long long val) {
        for (; i < (int)tree.size(); i += i & (-i)) tree[i] += val;
    }
    long long query(int i) {
        long long s = 0;
        for (; i > 0; i -= i & (-i)) s += tree[i];
        return s;
    }
};

class Solution {
public:
    vector<int> treeQueries(int n, vector<vector<int>>& edges, vector<vector<int>>& queries) {
        vector<vector<pair<int, int>>> graph(n + 1);
        map<pair<int, int>, int> edgeWeights;
        for (const auto& e : edges) {
            graph[e[0]].push_back({e[1], e[2]});
            graph[e[1]].push_back({e[0], e[2]});
            edgeWeights[{min(e[0], e[1]), max(e[0], e[1])}] = e[2];
        }

        vector<int> inTime(n + 1), outTime(n + 1), parent(n + 1);
        vector<long long> dist(n + 1);
        int timer = 0;

        auto dfs = [&](auto& self, int u, int p, long long d) -> void {
            inTime[u] = ++timer;
            parent[u] = p;
            dist[u] = d;
            for (const auto& [v, w] : graph[u]) {
                if (v != p) self(self, v, u, d + w);
            }
            outTime[u] = timer;
        };
        dfs(dfs, 1, 0, 0);

        Fenwick bit(n + 2);
        for (int i = 1; i <= n; ++i) {
            bit.add(inTime[i], dist[i]);
            bit.add(inTime[i] + 1, -dist[i]);
        }

        vector<int> ans;
        for (const auto& q : queries) {
            if (q[0] == 1) {
                int u = q[1], v = q[2], nw = q[3];
                auto key = make_pair(min(u, v), max(u, v));
                int delta = nw - edgeWeights[key];
                edgeWeights[key] = nw;
                int child = (parent[v] == u) ? v : u;
                bit.add(inTime[child], delta);
                bit.add(outTime[child] + 1, -delta);
            } else {
                int x = q[1];
                ans.push_back((int)bit.query(inTime[x]));
            }
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    static class Fenwick {
        long[] tree;
        Fenwick(int sz) { tree = new long[sz + 2]; }
        void add(int i, long val) {
            for (; i < tree.length; i += i & (-i)) tree[i] += val;
        }
        long query(int i) {
            long s = 0;
            for (; i > 0; i -= i & (-i)) s += tree[i];
            return s;
        }
    }

    public int[] treeQueries(int n, int[][] edges, int[][] queries) {
        List<int[]>[] graph = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) graph[i] = new ArrayList<>();
        Map<String, Integer> edgeWeights = new HashMap<>();
        for (int[] e : edges) {
            graph[e[0]].add(new int[]{e[1], e[2]});
            graph[e[1]].add(new int[]{e[0], e[2]});
            edgeWeights.put(Math.min(e[0], e[1]) + "#" + Math.max(e[0], e[1]), e[2]);
        }

        int[] inTime = new int[n + 1], outTime = new int[n + 1], parent = new int[n + 1];
        long[] dist = new long[n + 1];
        dfs(1, 0, 0, graph, inTime, outTime, parent, dist, new int[]{0});

        Fenwick bit = new Fenwick(n + 2);
        for (int i = 1; i <= n; i++) {
            bit.add(inTime[i], dist[i]);
            bit.add(inTime[i] + 1, -dist[i]);
        }

        List<Integer> res = new ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                int u = q[1], v = q[2], nw = q[3];
                String key = Math.min(u, v) + "#" + Math.max(u, v);
                int delta = nw - edgeWeights.get(key);
                edgeWeights.put(key, nw);
                int child = (parent[v] == u) ? v : u;
                bit.add(inTime[child], delta);
                bit.add(outTime[child] + 1, -delta);
            } else {
                int x = q[1];
                res.add((int) bit.query(inTime[x]));
            }
        }
        int[] ans = new int[res.size()];
        for (int i = 0; i < res.size(); i++) ans[i] = res.get(i);
        return ans;
    }

    private void dfs(int u, int p, long d, List<int[]>[] g, int[] inT, int[] outT, int[] par, long[] dist, int[] timer) {
        inT[u] = ++timer[0];
        par[u] = p;
        dist[u] = d;
        for (int[] edge : g[u]) {
            if (edge[0] != p) dfs(edge[0], u, d + edge[1], g, inT, outT, par, dist, timer);
        }
        outT[u] = timer[0];
    }
}

var treeQueries = function(n, edges, queries) {
    const graph = Array.from({ length: n + 1 }, () => []);
    const edgeWeights = new Map();
    for (const [u, v, w] of edges) {
        graph[u].push([v, w]);
        graph[v].push([u, w]);
        edgeWeights.set(`${Math.min(u, v)},${Math.max(u, v)}`, w);
    }

    const inTime = new Array(n + 1).fill(0);
    const outTime = new Array(n + 1).fill(0);
    const parent = new Array(n + 1).fill(0);
    const dist = new Array(n + 1).fill(0);
    let timer = 0;

    function dfs(u, p, d) {
        inTime[u] = ++timer;
        parent[u] = p;
        dist[u] = d;
        for (const [v, w] of graph[u]) {
            if (v !== p) dfs(v, u, d + w);
        }
        outTime[u] = timer;
    }
    dfs(1, 0, 0);

    const bit = new Array(n + 4).fill(0);
    const add = (i, val) => {
        for (; i < bit.length; i += i & -i) bit[i] += val;
    };
    const query = i => {
        let s = 0;
        for (; i > 0; i -= i & -i) s += bit[i];
        return s;
    };

    for (let i = 1; i <= n; i++) {
        add(inTime[i], dist[i]);
        add(inTime[i] + 1, -dist[i]);
    }

    const ans = [];
    for (const q of queries) {
        if (q[0] === 1) {
            const [_, u, v, nw] = q;
            const key = `${Math.min(u, v)},${Math.max(u, v)}`;
            const delta = nw - edgeWeights.get(key);
            edgeWeights.set(key, nw);
            const child = parent[v] === u ? v : u;
            add(inTime[child], delta);
            add(outTime[child] + 1, -delta);
        } else {
            ans.push(query(inTime[q[1]]));
        }
    }
    return ans;
};
